import React from 'react';
import { PlusCircle, Edit3, Trash2, Clock } from 'lucide-react';

const ActivityFeed = ({ activities = [] }) => {
  const getIcon = (type) => {
    switch (type) {
      case 'added':
        return <PlusCircle size={16} style={{ color: '#34d399' }} />;
      case 'edited':
        return <Edit3 size={16} style={{ color: '#fbbf24' }} />;
      case 'deleted':
        return <Trash2 size={16} style={{ color: '#f87171' }} />;
      default:
        return <Clock size={16} style={{ color: '#818cf8' }} />;
    }
  };

  const formatTime = (isoString) => {
    if (!isoString) return 'Just now';
    const date = new Date(isoString);
    return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) + ' - ' + date.toLocaleDateString();
  };

  if (!activities || activities.length === 0) {
    return (
      <div style={{ padding: '1.5rem', textAlign: 'center', color: 'var(--text-muted)' }}>
        No recent asset activities recorded yet.
      </div>
    );
  }

  return (
    <div className="activity-list" style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
      {activities.map((item, index) => (
        <div
          key={item.id || index}
          style={{
            display: 'flex',
            alignItems: 'flex-start',
            gap: '0.85rem',
            padding: '0.85rem 1rem',
            borderRadius: 'var(--radius-sm)',
            background: 'rgba(255, 255, 255, 0.02)',
            border: '1px solid rgba(255, 255, 255, 0.05)',
          }}
        >
          <div style={{ marginTop: '3px' }}>{getIcon(item.type)}</div>
          <div style={{ flex: 1 }}>
            <div style={{ fontSize: '0.88rem', color: 'var(--text-primary)', fontWeight: '600' }}>
              <span style={{ color: item.type === 'added' ? '#34d399' : item.type === 'edited' ? '#fbbf24' : '#f87171', textTransform: 'capitalize', marginRight: '4px' }}>
                {item.type}
              </span>
              {item.assetName || item.machineId}
              <span style={{ color: 'var(--text-muted)', fontSize: '0.8rem', fontWeight: 'normal', marginLeft: '6px' }}>
                ({item.machineId})
              </span>
            </div>
            {item.details && (
              <div style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', marginTop: '2px' }}>
                {item.details}
              </div>
            )}
            <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)', marginTop: '4px', display: 'flex', gap: '0.5rem', alignItems: 'center' }}>
              <span>By {item.user || 'System Engineer'}</span>
              <span>•</span>
              <span>{formatTime(item.timestamp)}</span>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
};

export default ActivityFeed;
